#include <iostream>
#include <list>
#include <set>
#include <algorithm>
using namespace std;

int main() {
   list<int> coll1;
   set<int> coll2;
   // Fill both collections with some sorted elements
   coll1.insert(coll1.end(), {1, 3, 5, 7});
   coll2.insert({2, 4, 6, 8});
   // Print elements of coll1
   cout << "coll1: ";
   for (const auto& elem : coll1) cout << elem << ' ';
   cout << endl;
   // Print elements of coll2
   cout << "coll2: ";
   for (const auto& elem : coll2) cout << elem << ' ';
   cout << endl;
   // Merge the two collections into a vector
   vector<int> merged;
   merged.reserve(coll1.size() + coll2.size());
   merged.insert(merged.end(), coll1.begin(), coll1.end());
   merged.insert(merged.end(), coll2.begin(), coll2.end());
   // Sort the merged sequence
   sort(merged.begin(), merged.end());
   // Print merged sequence
   cout << "merged: ";
   for (const auto& elem : merged) cout << elem << ' ';
   cout << endl;
   return 0;
}
